// Joins this week's scrape against every listing seen before, so the rest of the
// workflow can talk about what changed rather than about what exists.
//
// Two normalisations carry the whole comparison:
//
// - The listing URL is stripped of its query string. All three portals append
//   tracking parameters that differ between runs; matched raw, every listing
//   looks new every week and no price drop is ever detected.
// - Listings are keyed on the address, not the URL. The same house sits on all
//   three portals under three different URLs, and counting it three times
//   inflates every count in the report.

// Read Known Listings is set to always output data, so on the first Monday it
// emits one empty placeholder rather than nothing. Keying on its presence
// would put an undefined entry in the map.
const known = new Map();
for (const row of $('Read Known Listings').all()) {
  if (row.json?.dedupe_key) known.set(row.json.dedupe_key, row.json);
}

const today = $now.toISODate();

/** Portals write prices as "$1,250,000", "1.25M", or "From $980,000". */
function toNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'string') return null;
  const millions = /([\d.]+)\s*M\b/i.exec(value);
  if (millions) return Math.round(parseFloat(millions[1]) * 1000000);
  const parsed = parseFloat(value.replace(/,/g, '').replace(/[^\d.]/g, ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
}

/**
 * The listing URL without its query string, by string surgery rather than by
 * the URL constructor.
 *
 * The Code node's sandbox does not expose URL. Parsing through it threw on
 * every row, and because the throw was caught and turned into null, the
 * failure was silent: listings kept their address and lost their link, and the
 * only visible symptom was an empty source column.
 */
function canonicalUrl(value) {
  if (typeof value !== 'string') return null;
  const withoutQuery = value.trim().split('#')[0].split('?')[0];
  return /^https?:\/\/[^/]+/i.test(withoutQuery) ? withoutQuery.replace(/\/+$/, '') : null;
}

/**
 * The identity of a house, built only from the parts every portal agrees on.
 *
 * Portals disagree about the tail of an address. One writes "12500 Turkey
 * Ridge Ct, Austin TX 78729"; another glues the city straight onto the street
 * as "3228 Jewelfish CoveAustin, TX 78728", leaving nothing to mark where the
 * street ends — so no amount of trimming separates them reliably. The head of
 * an address is never ambiguous, so the key is the street number, the first
 * word of the street name, and the ZIP.
 *
 * The cost is condos: portals write unit numbers differently, so one can key
 * twice. A house cannot, and houses are the bulk of any listing page.
 */
function houseKey(address, zip) {
  const head = String(address ?? '')
    .trim()
    .match(/^(\d+)\s+([A-Za-z]+)/);
  return head && zip ? (head[1] + ' ' + head[2] + ' ' + zip).toLowerCase() : null;
}

/**
 * The ZIP, read from the end of the address rather than from the ZIP column.
 *
 * A US listing address ends with its ZIP, and the last five-digit token is
 * therefore the ZIP even when the street number is also five digits — "12500
 * Turkey Ridge Ct, Austin TX 78729". The dedicated column cannot be trusted
 * ahead of it: the mapper fills that same row's zip_code with 12500. The
 * column is still worth a fallback for cards that print no full address.
 *
 * Reading the address also sidesteps the leading zero the column loses when
 * the mapper types it as a number — 02134 arriving as 2134. The padding below
 * restores it, bounded by the real limits of the US ZIP range so a stray parse
 * cannot invent one.
 */
function toZip(row) {
  const inAddress = String(row.address ?? '').match(/\b\d{5}\b/g);
  if (inAddress) return inAddress[inAddress.length - 1];

  const field = row.zip_code;
  if (typeof field === 'number' && Number.isInteger(field) && field >= 501 && field <= 99950) {
    return String(field).padStart(5, '0');
  }
  const match = String(field ?? '').match(/\b\d{5}\b/);
  return match ? match[0] : null;
}

function daysBetween(from, to) {
  const ms = new Date(to).getTime() - new Date(from).getTime();
  return Number.isFinite(ms) ? Math.max(0, Math.round(ms / 86400000)) : 0;
}

const byKey = new Map();

for (const item of $input.all()) {
  const row = item.json.data ?? item.json;
  const listingUrl = canonicalUrl(row.listing_url);
  const zip = toZip(row);
  const key = houseKey(row.address, zip) ?? listingUrl;
  if (!key) continue;

  // First portal to list a house wins its row. Merge Sources fixes that order,
  // so the winner is stable between weeks and its price history stays one series.
  if (byKey.has(key)) continue;

  const price = toNumber(row.price);
  const sqft = toNumber(row.sqft);
  const previous = known.get(key);
  const previousPrice = previous ? toNumber(previous.price) : null;

  let status = 'unchanged';
  if (!previous) status = 'new';
  else if (previousPrice && price && price < previousPrice) status = 'price_drop';
  else if (previousPrice && price && price > previousPrice) status = 'price_rise';

  const firstSeen = previous?.first_seen || today;

  byKey.set(key, {
    dedupe_key: key,
    listing_url: listingUrl ?? '',
    address: String(row.address ?? '').trim(),
    zip_code: zip ?? '',
    source: listingUrl ? (listingUrl.split('/')[2] || '').replace('www.', '') : '',
    price,
    sqft,
    beds: toNumber(row.beds),
    baths: toNumber(row.baths),
    price_per_sqft: price && sqft ? Math.round(price / sqft) : null,
    status,
    previous_price: previousPrice,
    drop_pct: status === 'price_drop' ? Math.round(((previousPrice - price) / previousPrice) * 1000) / 10 : null,
    first_seen: firstSeen,
    last_seen: today,
    days_listed: daysBetween(firstSeen, today),
  });
}

return [...byKey.values()].map((json) => ({ json }));

// Every number in the report is computed here. The LLM downstream is handed the
// finished figures and asked only to explain them — a language model asked to
// take a median will produce a plausible one, and a market report that is
// plausibly wrong is worse than no report.

const CITY = 'Austin, TX';        // must match the city your three search URLs cover
const MIN_LISTINGS_PER_ZIP = 3;   // one house is not a neighbourhood median
const TOP_DROPS = 10;
const TOP_STALE = 5;
const TREND_WEEKS = 12;

// Read the comparison directly rather than through $input. This node sits
// downstream of the upsert, and a Data Table node emits the row it wrote — the
// stored columns only. The fields the report is built from (drop_pct,
// days_listed, previous_price) exist nowhere but here.
const listings = $('Compare With Last Week')
  .all()
  .map((item) => item.json);

function median(values) {
  if (!values.length) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : Math.round((sorted[mid - 1] + sorted[mid]) / 2);
}

function quantile(sorted, q) {
  const pos = (sorted.length - 1) * q;
  const base = Math.floor(pos);
  const rest = pos - base;
  const next = sorted[base + 1] ?? sorted[base];
  return sorted[base] + rest * (next - sorted[base]);
}

// A mis-parsed price or a 200-unit new-build block will otherwise drag the
// median it is supposed to be measured against. Tukey's fence, on price per
// square foot, drops both without needing a hand-set threshold.
function withoutOutliers(rows) {
  const values = rows.map((row) => row.price_per_sqft).sort((a, b) => a - b);
  if (values.length < 8) return rows;
  const q1 = quantile(values, 0.25);
  const q3 = quantile(values, 0.75);
  const fence = 1.5 * (q3 - q1);
  return rows.filter((row) => row.price_per_sqft >= q1 - fence && row.price_per_sqft <= q3 + fence);
}

const priced = withoutOutliers(listings.filter((row) => row.price_per_sqft > 0));

const byZip = new Map();
for (const row of priced) {
  if (!row.zip_code) continue;
  if (!byZip.has(row.zip_code)) byZip.set(row.zip_code, []);
  byZip.get(row.zip_code).push(row);
}

const zips = [...byZip.entries()]
  .filter(([, rows]) => rows.length >= MIN_LISTINGS_PER_ZIP)
  .map(([zip, rows]) => ({
    zip_code: zip,
    listing_count: rows.length,
    median_price: median(rows.map((row) => row.price)),
    median_price_per_sqft: median(rows.map((row) => row.price_per_sqft)),
  }))
  .sort((a, b) => b.median_price_per_sqft - a.median_price_per_sqft);

const medianPricePerSqft = median(priced.map((row) => row.price_per_sqft));
const medianPrice = median(priced.map((row) => row.price));

// Past weeks, oldest first. Week one has none — the trend chart is a single
// point until this has run twice, which is the honest shape rather than a
// fabricated baseline.
const history = $('Read Past Snapshots')
  .all()
  .map((row) => row.json)
  .filter((row) => row.week_of && Number(row.median_price_per_sqft) > 0)
  .sort((a, b) => String(a.week_of).localeCompare(String(b.week_of)))
  .slice(-(TREND_WEEKS - 1));

const lastWeek = history[history.length - 1] ?? null;
const wowChangePct = lastWeek
  ? Math.round(((medianPricePerSqft - Number(lastWeek.median_price_per_sqft)) / Number(lastWeek.median_price_per_sqft)) * 1000) / 10
  : null;

const weekOf = $now.toISODate();
const drops = listings
  .filter((row) => row.status === 'price_drop')
  .sort((a, b) => b.drop_pct - a.drop_pct)
  .slice(0, TOP_DROPS);
const stale = listings
  .filter((row) => row.days_listed >= 30)
  .sort((a, b) => b.days_listed - a.days_listed)
  .slice(0, TOP_STALE);
const fresh = listings.filter((row) => row.status === 'new');

const money = (value) => (value ? '$' + Number(value).toLocaleString('en-US') : 'n/a');

// Which portals actually contributed. A portal whose job has gone unusable
// simply stops appearing here, so the report shows a thinner market rather
// than quietly implying the whole city got cheaper.
const bySource = {};
for (const row of listings) {
  const source = row.source || 'unknown';
  bySource[source] = (bySource[source] ?? 0) + 1;
}
const sources = Object.entries(bySource).sort((a, b) => b[1] - a[1]);

const brief = [
  'CITY: ' + CITY,
  'WEEK OF: ' + weekOf,
  '',
  'MARKET',
  '- Listings tracked this week: ' + listings.length + ' (' + fresh.length + ' new since last week)',
  '- Portals contributing: ' + (sources.length ? sources.map(([name, n]) => name + ' ' + n).join(', ') : 'none'),
  '- Median asking price: ' + money(medianPrice),
  '- Median price per square foot: ' + money(medianPricePerSqft),
  '- Week over week on price per square foot: ' + (wowChangePct === null ? 'no prior week yet' : wowChangePct + '%'),
  '- Listings that cut their price this week: ' + drops.length,
  '',
  'BY ZIP CODE (median price per square foot, high to low)',
  ...zips.map((zip) => '- ' + zip.zip_code + ': ' + money(zip.median_price_per_sqft) + '/sqft, median ' + money(zip.median_price) + ', ' + zip.listing_count + ' listings'),
  '',
  'PRICE CUTS THIS WEEK',
  ...(drops.length
    ? drops.map((row) => '- ' + (row.address || row.listing_url) + ' (' + row.zip_code + '): ' + money(row.previous_price) + ' -> ' + money(row.price) + ', down ' + row.drop_pct + '%, ' + row.days_listed + ' days listed')
    : ['- none']),
  '',
  'SITTING LONGEST',
  ...(stale.length
    ? stale.map((row) => '- ' + (row.address || row.listing_url) + ' (' + row.zip_code + '): ' + money(row.price) + ', ' + row.days_listed + ' days listed')
    : ['- nothing over 30 days yet']),
].join('\n');

return [
  {
    json: {
      city: CITY,
      week_of: weekOf,
      listing_count: listings.length,
      new_count: fresh.length,
      price_drop_count: drops.length,
      median_price: medianPrice,
      median_price_per_sqft: medianPricePerSqft,
      wow_change_pct: wowChangePct,
      sources: sources.map(([name, count]) => ({ source: name, listing_count: count })),
      zips,
      drops,
      stale,
      brief,
      zip_labels: zips.map((zip) => zip.zip_code),
      zip_values: zips.map((zip) => zip.median_price_per_sqft),
      trend_labels: [...history.map((row) => String(row.week_of)), weekOf],
      trend_values: [...history.map((row) => Number(row.median_price_per_sqft)), medianPricePerSqft],
    },
  },
];

// Carries both chart images onto the item that leaves the workflow.
//
// Binary does not travel with $json: a node that reads only the LLM's text
// output drops the PNGs QuickChart produced upstream, and the report arrives
// with nothing to look at. Naming both binary fields here is what makes a Gmail
// or Slack node downstream a one-node change.

const stats = $('Compute Market Stats').first().json;
const commentary = $input.first().json.text ?? '';

const money = (value) => (value ? '$' + Number(value).toLocaleString('en-US') : 'n/a');
const direction = stats.wow_change_pct === null ? '' : (stats.wow_change_pct >= 0 ? 'up ' : 'down ') + Math.abs(stats.wow_change_pct) + '% on last week';

const report = [
  '# ' + stats.city + ' market report — week of ' + stats.week_of,
  '',
  '**' + stats.listing_count + ' listings tracked** · median ' + money(stats.median_price) +
    ' · ' + money(stats.median_price_per_sqft) + '/sqft' + (direction ? ' · ' + direction : ''),
  '**' + stats.new_count + ' new this week** · **' + stats.price_drop_count + ' price cuts**',
  '',
  'From ' + (stats.sources ?? []).map((s) => s.source + ' (' + s.listing_count + ')').join(', '),
  '',
  commentary.trim(),
  '',
  '---',
  '',
  'Charts attached: median price per square foot by ZIP, and the city median by week.',
].join('\n');

return [
  {
    json: { ...stats, commentary, report },
    binary: {
      ...($('Median Price per Sqft by ZIP').first().binary ?? {}),
      ...($('City Trend by Week').first().binary ?? {}),
    },
  },
];
